def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

test_k = [1, 4, 10]
results = {}

for k in test_k:
    N = 2 * (k**3)
    d_N = count_divisors(N)
    expected = 2 * k
    is_satisfied = d_N == expected
    results[k] = (N, d_N, expected, is_satisfied)

print("Verification Results:")
for k, (N, d_N, expected, is_satisfied) in results.items():
    print(f"k = {k}:")
    print(f"  N = 2k^3 = {N}")
    print(f"  d(N) = {d_N}")
    print(f"  2k = {expected}")
    print(f"  Satisfied? {is_satisfied}")
